import numpy as np

def find_min_r(S):
    k_sq = -2*S**2 - 9*S
    if k_sq < 0:
        return None
    k = np.sqrt(k_sq)
    r1 = (7*S**3 + 27*S**2 - 2*k**3) / 27
    r2 = (7*S**3 + 27*S**2 + 2*k**3) / 27
    return min(r1, r2)

min_r = 100
for S in np.linspace(-4.5, 0, 1000):
    r = find_min_r(S)
    if r is not None and r < min_r:
        min_r = r

print(f"Min r: {min_r}")
